window.CODE_INDEX = {"classes":{"BackPressedHandler":{"code":"interface BackPressedHandler {\n    fun onBackPressed(): Boolean\n}","file":"app/src/main/java/org/wikipedia/BackPressedHandler.kt","kind":"interface","line":3,"members":{"onBackPressed":[4,4]},"supers":[]},"HistoryFragment":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["search","h-classes","Logic \u00b7 class diagram"]],"code":"class HistoryFragment : Fragment(), BackPressedHandler {\n    interface Callback {\n        fun onLoadPage(entry: HistoryEntry)\n    }\n\n    private var _binding: FragmentHistoryBinding? = null\n    private val binding get() = _binding!!\n    private val viewModel: HistoryViewModel by viewModels()\n\n    private val adapter = HistoryEntryItemAdapter()\n    private val itemCallback = ItemCallback()\n    private var actionMode: ActionMode? = null\n    private val searchActionModeCallback = HistorySearchCallback()\n    private val selectedEntries = mutableSetOf<HistoryEntry>()\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = FragmentHistoryBinding.inflate(inflater, container, false)\n\n        binding.searchEmptyView.setEmptyText(R.string.search_history_no_results)\n        val touchCallback = SwipeableItemTouchHelperCallback(requireContext())\n        touchCallback.swipeableEnabled = true\n        val itemTouchHelper = ItemTouchHelper(touchCallback)\n        itemTouchHelper.attachToRecyclerView(binding.historyList)\n        binding.historyList.layoutManager = LinearLayoutManager(context)\n        binding.historyList.adapter = adapter\n        binding.historyEmptyContainer.visibility = View.GONE\n        setUpScrollListener()\n        return binding.root\n    }\n\n    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {\n        super.onViewCreated(view, savedInstanceState)\n\n        viewModel.historyItems.observe(viewLifecycleOwner) {\n            if (it is Resource.Success) {\n                onLoadItemsFinished(it.data)\n            } else if (it is Resource.Error) {\n                onError(it.throwable)\n            }\n        }\n\n        viewModel.deleteHistoryItemsAction.observe(viewLifecycleOwner) {\n            if (it is Resource.Success) {\n                onPagesDeleted()\n            }\n        }\n    }\n\n    private fun setUpScrollListener() {\n        binding.historyList.addOnScrollListener(object : RecyclerView.OnScrollListener() {\n            override fun onScrolled(recyclerView: RecyclerView, dx: Int, dy: Int) {\n                super.onScrolled(recyclerView, dx, dy)\n                (requireActivity() as MainActivity).updateToolbarElevation(binding.historyList.computeVerticalScrollOffset() != 0)\n            }\n        })\n    }\n\n    override fun onResume() {\n        super.onResume()\n        viewModel.reloadHistoryItems()\n    }\n\n    override fun onPause() {\n        super.onPause()\n        actionMode?.finish()\n    }\n\n    override fun onDestroyView() {\n        binding.historyList.adapter = null\n        binding.historyList.clearOnScrollListeners()\n        adapter.clearList()\n        _binding = null\n        super.onDestroyView()\n    }\n\n    override fun onBackPressed(): Boolean {\n        actionMode?.run {\n            finish()\n            return@onBackPressed true\n        }\n        if (selectedEntries.size > 0) {\n            unselectAllPages()\n            return true\n        }\n        return false\n    }\n\n    private fun updateEmptyState(searchQuery: String?) {\n        if (searchQuery.isNullOrEmpty()) {\n            binding.searchEmptyView.visibility = View.GONE\n            binding.historyEmptyContainer.visibility = if (adapter.isEmpty) View.VISIBLE else View.GONE\n        } else {\n            binding.searchEmptyView.visibility = if (adapter.isEmpty) View.VISIBLE else View.GONE\n            binding.historyEmptyContainer.visibility = View.GONE\n        }\n    }\n\n    private fun onPageClick(entry: HistoryEntry) {\n        callback()?.onLoadPage(entry)\n    }\n\n    private fun finishActionMode() {\n        actionMode?.finish()\n    }\n\n    private fun beginMultiSelect() {\n        if (SearchActionModeCallback.matches(actionMode)) {\n            finishActionMode()\n        }\n    }\n\n    private fun toggleSelectPage(entry: HistoryEntry?) {\n        if (entry == null) {\n            return\n        }\n        if (selectedEntries.contains(entry)) {\n            selectedEntries.remove(entry)\n        } else {\n            selectedEntries.add(entry)\n        }\n        val selectedCount = selectedEntries.size\n        if (selectedCount == 0) {\n            finishActionMode()\n        } else {\n            actionMode?.title = resources.getQuantityString(R.plurals.multi_items_selected, selectedCount, selectedCount)\n        }\n        val position = adapter.getPosition(entry)\n        adapter.notifyItemChanged(position)\n    }\n\n    fun refresh() {\n        adapter.notifyItemRangeChanged(0, adapter.itemCount)\n        if (!WikipediaApp.instance.isOnline && Prefs.showHistoryOfflineArticlesToast) {\n            Toast.makeText(requireContext(), R.string.history_offline_articles_toast, Toast.LENGTH_SHORT).show()\n            Prefs.showHistoryOfflineArticlesToast = false\n        }\n    }\n\n    private fun unselectAllPages() {\n        selectedEntries.clear()\n        adapter.notifyItemRangeChanged(0, adapter.itemCount)\n    }\n\n    private fun deleteSelectedPages() {\n        viewModel.deleteHistoryItems(selectedEntries.toList())\n    }\n\n    private fun onPagesDeleted() {\n        showDeleteItemsUndoSnackbar(selectedEntries.toList())\n        selectedEntries.clear()\n        viewModel.reloadHistoryItems()\n    }\n\n    private fun showDeleteItemsUndoSnackbar(entries: List<HistoryEntry>) {\n        val message = if (entries.size == 1) getString(R.string.history_item_deleted, entries[0].title.displayText) else getString(R.string.history_items_deleted, entries.size)\n        val snackbar = FeedbackUtil.makeSnackbar(requireActivity(), message)\n        snackbar.setAction(R.string.history_item_delete_undo) {\n            viewModel.insertHistoryItem(entries)\n        }\n        snackbar.show()\n    }\n\n    private fun onLoadItemsFinished(items: List<Any>) {\n        val list = mutableListOf<Any>()\n        if (!SearchActionModeCallback.matches(actionMode)) {\n            list.add(SearchBar())\n        }\n        list.addAll(items)\n        adapter.setList(list)\n        updateEmptyState(viewModel.searchQuery)\n        requireActivity().invalidateOptionsMenu()\n    }\n\n    private fun onError(throwable: Throwable) {\n        L.e(throwable)\n        onLoadItemsFinished(emptyList())\n    }\n\n    private class HeaderViewHolder(itemView: View) : DefaultViewHolder<View>(itemView) {\n        var headerText = itemView.findViewById<TextView>(R.id.section_header_text)!!\n\n        fun bindItem(date: String) {\n            headerText.text = date\n        }\n    }\n\n    private inner class SearchCardViewHolder(itemView: View) : DefaultViewHolder<View>(itemView) {\n        private val historyFilterButton: ImageView\n        private val clearHistoryButton: ImageView\n\n        fun bindItem() {\n            clearHistoryButton.visibility = if (adapter.isEmpty) View.GONE else View.VISIBLE\n            historyFilterButton.visibility = if (adapter.isEmpty) View.GONE else View.VISIBLE\n        }\n\n        private fun adjustSearchCardView(searchCardView: WikiCardView) {\n            searchCardView.post {\n                if (!isAdded) {\n                    return@post\n                }\n                searchCardView.updateLayoutParams<LinearLayout.LayoutParams> {\n                    val horizontalMargin = if (DimenUtil.isLandscape(requireContext())) {\n                        searchCardView.width / 6 + DimenUtil.roundedDpToPx(30f)\n                    } else {\n                        DimenUtil.roundedDpToPx(16f)\n                    }\n                    updateMarginsRelative(start = horizontalMargin, end = horizontalMargin,\n                        top = DimenUtil.roundedDpToPx(3f))\n                }\n            }\n            searchCardView.setCardBackgroundColor(ResourceUtil.getThemedColor(requireContext(), R.attr.background_color))\n        }\n\n        init {\n            val searchCardView = itemView.findViewById<WikiCardView>(R.id.search_card)\n            val voiceSearchButton = itemView.findViewById<View>(R.id.voice_search_button)\n            historyFilterButton = itemView.findViewById(R.id.history_filter)\n            clearHistoryButton = itemView.findViewById(R.id.history_delete)\n            searchCardView.setOnClickListener { (requireParentFragment() as MainFragment).openSearchActivity(Constants.InvokeSource.NAV_MENU, null, it) }\n            voiceSearchButton.isVisible = WikipediaApp.instance.voiceRecognitionAvailable\n            voiceSearchButton.setOnClickListener { (requireParentFragment() as MainFragment).onFeedVoiceSearchRequested() }\n            historyFilterButton.setOnClickListener {\n                if (actionMode == null) {\n                    actionMode = (requireActivity() as AppCompatActivity)\n                            .startSupportActionMode(searchActionModeCallback)\n                }\n            }\n            clearHistoryButton.setOnClickListener {\n                if (selectedEntries.isEmpty()) {\n                    clearAllHistory(requireContext(), lifecycleScope) {\n                        viewModel.afterDeleteAllHistoryItems()\n                    }\n                } else {\n                    deleteSelectedPages()\n                }\n            }\n            FeedbackUtil.setButtonTooltip(historyFilterButton, clearHistoryButton)\n            adjustSearchCardView(searchCardView)\n            updateSearchHint(searchCardView.findViewById(R.id.search_icon), searchCardView.findViewById(R.id.search_text_view))\n        }\n\n        private fun updateSearchHint(searchIcon: ImageView, searchTextView: TextView) {\n            searchIcon.contentDescription = getString(R.string.search_hint)\n            searchTextView.text = getString(R.string.search_hint)\n        }\n    }\n\n    private inner class HistoryEntryItemHolder(itemView: PageItemView<HistoryEntry>) : DefaultViewHolder<PageItemView<HistoryEntry>>(itemView), SwipeableItemTouchHelperCallback.Callback {\n        private lateinit var entry: HistoryEntry\n\n        fun bindItem(entry: HistoryEntry) {\n            this.entry = entry\n            view.item = entry\n            view.setTitle(entry.title.displayText)\n            view.setTitleTypeface(Typeface.NORMAL)\n            view.setDescription(entry.title.description)\n            view.setImageUrl(entry.title.thumbUrl)\n            view.setSearchQuery(viewModel.searchQuery)\n            view.isSelected = selectedEntries.contains(entry)\n            PageAvailableOfflineHandler.check(lifecycleScope, entry.title) { view.setViewsGreyedOut(!it) }\n        }\n\n        override fun onSwipe() {\n            selectedEntries.add(entry)\n            deleteSelectedPages()\n        }\n\n        override fun isSwipeable(): Boolean { return true }\n    }\n\n    private inner class HistoryEntryItemAdapter : RecyclerView.Adapter<DefaultViewHolder<*>>() {\n        private var historyEntries = mutableListOf<Any>()\n        override fun getItemCount(): Int {\n            return historyEntries.size\n        }\n\n        val isEmpty\n            get() = (itemCount == 0 || itemCount == 1 && historyEntries[0] is SearchBar)\n\n        override fun getItemViewType(position: Int): Int {\n            return when {\n                historyEntries[position] is SearchBar -> VIEW_TYPE_SEARCH_CARD\n                historyEntries[position] is String -> VIEW_TYPE_HEADER\n                else -> VIEW_TYPE_ITEM\n            }\n        }\n\n        fun setList(list: MutableList<Any>) {\n            historyEntries = list\n            adapter.notifyDataSetChanged()\n        }\n\n        fun clearList() {\n            historyEntries.clear()\n        }\n\n        fun getPosition(entry: HistoryEntry): Int {\n            return historyEntries.indexOf(entry)\n        }\n\n        override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): DefaultViewHolder<*> {\n            return when (viewType) {\n                VIEW_TYPE_SEARCH_CARD -> {\n                    val view = LayoutInflater.from(requireContext()).inflate(R.layout.view_history_header_with_search, parent, false)\n                    SearchCardViewHolder(view)\n                }\n                VIEW_TYPE_HEADER -> {\n                    val view = LayoutInflater.from(requireContext()).inflate(R.layout.view_section_header, parent, false)\n                    HeaderViewHolder(view)\n                }\n                else -> HistoryEntryItemHolder(PageItemView(requireContext()))\n            }\n        }\n\n        override fun onBindViewHolder(holder: DefaultViewHolder<*>, pos: Int) {\n            when (holder) {\n                is SearchCardViewHolder -> holder.bindItem()\n                is HistoryEntryItemHolder -> holder.bindItem(historyEntries[pos] as HistoryEntry)\n                else -> (holder as HeaderViewHolder).bindItem(historyEntries[pos] as String)\n            }\n        }\n\n        override fun onViewAttachedToWindow(holder: DefaultViewHolder<*>) {\n            super.onViewAttachedToWindow(holder)\n            if (holder is HistoryEntryItemHolder) {\n                holder.view.callback = itemCallback\n            }\n        }\n\n        override fun onViewDetachedFromWindow(holder: DefaultViewHolder<*>) {\n            if (holder is HistoryEntryItemHolder) {\n                holder.view.callback = null\n            }\n            super.onViewDetachedFromWindow(holder)\n        }\n\n        fun hideHeader() {\n            if (historyEntries.isNotEmpty() && historyEntries[0] is SearchBar) {\n                historyEntries.removeAt(0)\n                adapter.notifyItemRemoved(0)\n            }\n        }\n    }\n\n    private inner class ItemCallback : PageItemView.Callback<HistoryEntry?> {\n        override fun onClick(item: HistoryEntry?) {\n            if (selectedEntries.isNotEmpty()) {\n                toggleSelectPage(item)\n            } else if (item != null) {\n                onPageClick(HistoryEntry(item.title, HistoryEntry.SOURCE_HISTORY))\n            }\n        }\n\n        override fun onLongClick(item: HistoryEntry?): Boolean {\n            if (actionMode != null) {\n                return false\n            }\n            beginMultiSelect()\n            toggleSelectPage(item)\n            return true\n        }\n\n        override fun onActionClick(item: HistoryEntry?, view: View) {}\n        override fun onListChipClick(readingList: ReadingList) {}\n    }\n\n    private inner class HistorySearchCallback : SearchActionModeCallback() {\n        override fun onCreateActionMode(mode: ActionMode, menu: Menu): Boolean {\n            actionMode = mode\n            (requireParentFragment() as MainFragment).setBottomNavVisible(false)\n            (binding.historyList.adapter as HistoryEntryItemAdapter).hideHeader()\n            return super.onCreateActionMode(mode, menu)\n        }\n\n        override fun onQueryChange(s: String) {\n            viewModel.searchQuery = s.trim()\n        }\n\n        override fun onDestroyActionMode(mode: ActionMode) {\n            super.onDestroyActionMode(mode)\n            viewModel.searchQuery = \"\"\n            actionMode = null\n            (requireParentFragment() as MainFragment).setBottomNavVisible(true)\n        }\n\n        override fun getSearchHintString(): String {\n            return requireContext().resources.getString(R.string.history_filter_list_hint)\n        }\n\n        override fun getParentContext(): Context {\n            return requireContext()\n        }\n    }\n\n    private fun callback(): Callback? {\n        return FragmentUtil.getCallback(this, Callback::class.java)\n    }\n\n    private class SearchBar\n\n    companion object {\n        private const val VIEW_TYPE_SEARCH_CARD = 0\n        private const val VIEW_TYPE_HEADER = 1\n        private const val VIEW_TYPE_ITEM = 2\n\n        fun clearAllHistory(context: Context, coroutineScope: CoroutineScope, action: () -> Unit) {\n            MaterialAlertDialogBuilder(context)\n                .setTitle(R.string.dialog_title_clear_history)\n                .setMessage(R.string.dialog_message_clear_history)\n                .setPositiveButton(R.string.dialog_message_clear_history_yes) { _, _ ->\n                    coroutineScope.launch(\n                        CoroutineExceptionHandler { _, t -> L.e(t) }\n                    ) {\n                        AppDatabase.instance.historyEntryDao().deleteAll()\n                        AppDatabase.instance.pageImagesDao().deleteAll()\n                        AppDatabase.instance.categoryDao().deleteAll()\n                        AppDatabase.instance.pageTopicDao().deleteAll()\n                        PrefsYearInReviewStore.onReadingHistoryCleared()\n                        action()\n                    }\n                }\n                .setNegativeButton(R.string.dialog_message_clear_history_no, null).show()\n        }\n\n        fun newInstance(): HistoryFragment {\n            return HistoryFragment()\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/history/HistoryFragment.kt","kind":"class","line":52,"members":{"Callback":[53,55],"HeaderViewHolder":[230,236],"HistoryEntryItemAdapter":[322,394],"HistoryEntryItemHolder":[299,320],"HistorySearchCallback":[418,444],"ItemCallback":[396,416],"SearchBar":[450,450],"SearchCardViewHolder":[238,297],"VIEW_TYPE_HEADER":[454,454],"VIEW_TYPE_ITEM":[455,455],"VIEW_TYPE_SEARCH_CARD":[453,453],"_binding":[57,57],"actionMode":[63,63],"adapter":[61,61],"beginMultiSelect":[157,161],"binding":[58,58],"callback":[446,448],"clearAllHistory":[457,474],"deleteSelectedPages":[195,197],"finishActionMode":[153,155],"itemCallback":[62,62],"newInstance":[476,478],"onBackPressed":[127,137],"onCreateView":[67,80],"onDestroyView":[119,125],"onError":[225,228],"onLoadItemsFinished":[214,223],"onPageClick":[149,151],"onPagesDeleted":[199,203],"onPause":[114,117],"onResume":[109,112],"onViewCreated":[82,98],"refresh":[182,188],"searchActionModeCallback":[64,64],"selectedEntries":[65,65],"setUpScrollListener":[100,107],"showDeleteItemsUndoSnackbar":[205,212],"toggleSelectPage":[163,180],"unselectAllPages":[190,193],"updateEmptyState":[139,147],"viewModel":[59,59]},"shot":"shots/code/HistoryFragment.jpg","supers":["Fragment()","BackPressedHandler"]},"HistoryViewModel":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"]],"code":"class HistoryViewModel : ViewModel() {\n\n    private val handler = CoroutineExceptionHandler { _, throwable ->\n        historyItems.postValue(Resource.Error(throwable))\n    }\n\n    private var searchJob: Job? = null\n\n    var searchQuery: String? = null\n        set(value) {\n            field = value\n            searchJob?.cancel()\n            searchJob = viewModelScope.launch {\n                delay(500)\n                reloadHistoryItems()\n            }\n        }\n\n    val historyItems = MutableLiveData(Resource<List<Any>>())\n    val deleteHistoryItemsAction = SingleLiveData<Resource<Boolean>>()\n\n    init {\n        reloadHistoryItems()\n    }\n\n    fun reloadHistoryItems() {\n        viewModelScope.launch(handler) {\n            loadHistoryItems()\n        }\n    }\n\n    private suspend fun loadHistoryItems() {\n        withContext(Dispatchers.IO) {\n            val items = AppDatabase.instance.historyEntryWithImageDao().filterHistoryItems(searchQuery.orEmpty())\n            historyItems.postValue(Resource.Success(items))\n        }\n    }\n\n    fun afterDeleteAllHistoryItems() {\n        viewModelScope.launch(handler) {\n            historyItems.postValue(Resource.Success(emptyList()))\n        }\n    }\n\n    fun deleteHistoryItems(entries: List<HistoryEntry>) {\n        viewModelScope.launch(handler) {\n            entries.forEach {\n                AppDatabase.instance.historyEntryDao().delete(it)\n            }\n            deleteHistoryItemsAction.postValue(Resource.Success(true))\n        }\n    }\n\n    fun insertHistoryItem(entries: List<HistoryEntry>) {\n        viewModelScope.launch(handler) {\n            AppDatabase.instance.historyEntryDao().insert(entries)\n            loadHistoryItems()\n        }\n    }\n\n    override fun onCleared() {\n        super.onCleared()\n        searchJob?.cancel()\n    }\n}","file":"app/src/main/java/org/wikipedia/history/HistoryViewModel.kt","kind":"class","line":16,"members":{"afterDeleteAllHistoryItems":[54,58],"deleteHistoryItems":[60,67],"deleteHistoryItemsAction":[35,35],"handler":[18,20],"historyItems":[34,34],"insertHistoryItem":[69,74],"loadHistoryItems":[47,52],"onCleared":[76,79],"reloadHistoryItems":[41,45],"searchJob":[22,22],"searchQuery":[24,24]},"supers":["ViewModel()"]},"RecentSearchesFragment":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"]],"code":"class RecentSearchesFragment : Fragment() {\n    interface Callback {\n        fun switchToSearch(text: String)\n        fun onAddLanguageClicked()\n        fun getLangCode(): String\n    }\n\n    private var _binding: FragmentSearchRecentBinding? = null\n    val binding get() = _binding!!\n    private val namespaceHints = listOf(Namespace.USER, Namespace.PORTAL, Namespace.HELP, Namespace.PROJECT, Namespace.TEMPLATE)\n    private val namespaceMap = ConcurrentHashMap<String, Map<Namespace, String>>()\n    private val coroutineExceptionHandler = CoroutineExceptionHandler { _, throwable -> L.e(throwable) }\n    var callback: Callback? = null\n    val recentSearchList = mutableListOf<RecentSearch>()\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = FragmentSearchRecentBinding.inflate(inflater, container, false)\n\n        binding.recentSearchesDeleteButton.setOnClickListener {\n            MaterialAlertDialogBuilder(requireContext())\n                    .setMessage(getString(R.string.clear_recent_searches_confirm))\n                    .setPositiveButton(getString(R.string.clear_recent_searches_confirm_yes)) { _, _ ->\n                        lifecycleScope.launch(coroutineExceptionHandler) {\n                            AppDatabase.instance.recentSearchDao().deleteAll()\n                            updateList()\n                        }\n                    }\n                    .setNegativeButton(getString(R.string.clear_recent_searches_confirm_no), null)\n                    .show()\n        }\n        binding.addLanguagesButton.setOnClickListener { onAddLangButtonClick() }\n        binding.recentSearchesRecycler.layoutManager = LinearLayoutManager(requireActivity())\n        binding.namespacesRecycler.layoutManager = LinearLayoutManager(requireActivity(), RecyclerView.HORIZONTAL, false)\n\n        binding.recentSearchesRecycler.adapter = RecentSearchAdapter()\n\n        val touchCallback = SwipeableItemTouchHelperCallback(requireContext())\n        touchCallback.swipeableEnabled = true\n        val itemTouchHelper = ItemTouchHelper(touchCallback)\n        itemTouchHelper.attachToRecyclerView(binding.recentSearchesRecycler)\n        setButtonTooltip(binding.recentSearchesDeleteButton)\n\n        return binding.root\n    }\n\n    fun show() {\n        binding.recentSearchesContainer.visibility = View.VISIBLE\n    }\n\n    fun hide() {\n        binding.recentSearchesContainer.visibility = View.GONE\n    }\n\n    override fun onDestroyView() {\n        super.onDestroyView()\n        _binding = null\n    }\n\n    private fun updateSearchEmptyView(searchesEmpty: Boolean) {\n        if (searchesEmpty) {\n            binding.searchEmptyContainer.visibility = View.VISIBLE\n            if (WikipediaApp.instance.languageState.appLanguageCodes.size == 1) {\n                binding.addLanguagesButton.visibility = View.VISIBLE\n                binding.searchEmptyMessage.text = getString(R.string.search_empty_message_multilingual_upgrade)\n            } else {\n                binding.addLanguagesButton.visibility = View.GONE\n                binding.searchEmptyMessage.text = getString(R.string.search_empty_message)\n            }\n        } else {\n            binding.searchEmptyContainer.visibility = View.INVISIBLE\n        }\n    }\n\n    private fun onAddLangButtonClick() {\n        callback?.onAddLanguageClicked()\n    }\n\n    fun reloadRecentSearches() {\n        lifecycleScope.launch(coroutineExceptionHandler) {\n            updateList()\n        }\n    }\n\n    suspend fun updateList() {\n        val nsMap: Map<String, MwQueryResult.Namespace>\n        val langCode = callback?.getLangCode().orEmpty()\n\n        if (!namespaceMap.containsKey(langCode)) {\n            val map = mutableMapOf<Namespace, String>()\n            namespaceMap[langCode] = map\n            nsMap = ServiceFactory.get(WikiSite.forLanguageCode(langCode)).getPageNamespaceWithSiteInfo(null).query?.namespaces.orEmpty()\n            namespaceHints.forEach {\n                map[it] = nsMap[it.code().toString()]?.name.orEmpty()\n            }\n        }\n\n        val searches: List<RecentSearch> = AppDatabase.instance.recentSearchDao().getRecentSearches()\n\n        recentSearchList.clear()\n        recentSearchList.addAll(searches)\n\n        val searchesEmpty = recentSearchList.isEmpty()\n        binding.namespacesRecycler.adapter = NamespaceAdapter()\n        binding.recentSearchesRecycler.adapter?.notifyDataSetChanged()\n        binding.searchEmptyContainer.isInvisible = !searchesEmpty\n        updateSearchEmptyView(searchesEmpty)\n        binding.recentSearches.isInvisible = searchesEmpty\n        binding.namespacesContainer.isVisible = !namespaceMap[langCode].isNullOrEmpty()\n    }\n\n    private open inner class RecentSearchItemViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView), View.OnClickListener, SwipeableItemTouchHelperCallback.Callback {\n        private lateinit var recentSearch: RecentSearch\n\n        open fun bindItem(position: Int) {\n            recentSearch = recentSearchList[position]\n            itemView.setOnClickListener(this)\n            (itemView as TextView).text = recentSearch.text\n        }\n\n        override fun onClick(v: View) {\n            val text = (v as TextView).text.toString()\n\n            callback?.switchToSearch(text)\n        }\n\n        override fun onSwipe() {\n            lifecycleScope.launch(coroutineExceptionHandler) {\n                AppDatabase.instance.recentSearchDao().delete(recentSearch)\n                updateList()\n            }\n        }\n\n        override fun isSwipeable(): Boolean { return true }\n    }\n\n    private inner class RecentSearchAdapter : RecyclerView.Adapter<RecentSearchItemViewHolder>() {\n        override fun getItemCount(): Int {\n            return recentSearchList.size\n        }\n\n        override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): RecentSearchItemViewHolder {\n            return RecentSearchItemViewHolder(LayoutInflater.from(parent.context).inflate(R.layout.item_search_recent, parent, false))\n        }\n\n        override fun onBindViewHolder(holder: RecentSearchItemViewHolder, pos: Int) {\n            holder.bindItem(pos)\n        }\n    }\n\n    private inner class NamespaceItemViewHolder(itemView: View) : RecyclerView.ViewHolder(itemView), View.OnClickListener {\n        fun bindItem(ns: Namespace?) {\n            val isHeader = ns == null\n            (itemView as TextView).apply {\n                setOnClickListener(this@NamespaceItemViewHolder)\n                text = if (isHeader) getString(R.string.search_namespaces) else namespaceMap[callback?.getLangCode()]?.get(ns).orEmpty() + \":\"\n                isEnabled = !isHeader\n                setTextColor(ResourceUtil.getThemedColor(requireContext(), if (isHeader) R.attr.primary_color else R.attr.progressive_color))\n            }\n        }\n\n        override fun onClick(v: View) {\n            callback?.switchToSearch((v as TextView).text.toString())\n        }\n    }\n\n    private inner class NamespaceAdapter : RecyclerView.Adapter<NamespaceItemViewHolder>() {\n        override fun getItemCount(): Int {\n            return namespaceHints.size + 1\n        }\n\n        override fun onCreateViewHolder(parent: ViewGroup, viewType: Int): NamespaceItemViewHolder {\n            return NamespaceItemViewHolder(LayoutInflater.from(parent.context).inflate(R.layout.item_namespace, parent, false))\n        }\n\n        override fun onBindViewHolder(holder: NamespaceItemViewHolder, pos: Int) {\n            holder.bindItem(namespaceHints.getOrNull(pos - 1))\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/search/RecentSearchesFragment.kt","kind":"class","line":33,"members":{"Callback":[34,38],"NamespaceAdapter":[198,210],"NamespaceItemViewHolder":[182,196],"RecentSearchAdapter":[168,180],"RecentSearchItemViewHolder":[143,166],"_binding":[40,40],"binding":[41,41],"callback":[45,45],"coroutineExceptionHandler":[44,44],"hide":[82,84],"namespaceHints":[42,42],"namespaceMap":[43,43],"onAddLangButtonClick":[106,108],"onCreateView":[48,76],"onDestroyView":[86,89],"recentSearchList":[46,46],"reloadRecentSearches":[110,114],"show":[78,80],"updateList":[116,141],"updateSearchEmptyView":[91,104]},"shot":"shots/code/RecentSearchesFragment.jpg","supers":["Fragment()"]},"SearchActivity":{"appearsIn":[["index","h-screens","Screens \u00b7 how the user moves"],["search","h-classes","Logic \u00b7 class diagram"]],"code":"class SearchActivity : SingleFragmentActivity<SearchFragment>() {\n\n    private val onBackPressedCallback = object : OnBackPressedCallback(true) {\n        override fun handleOnBackPressed() {\n\n            instrument?.submitInteraction(\"click\", elementId = \"search_back\")\n\n            isEnabled = false\n            onBackPressedDispatcher.onBackPressed()\n        }\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        if (intent.hasExtra(EXTRA_SHOW_SNACKBAR_MESSAGE)) {\n            val messageResId = intent.getIntExtra(EXTRA_SHOW_SNACKBAR_MESSAGE, 0)\n            if (messageResId != 0) {\n                FeedbackUtil.showMessage(this, messageResId)\n                intent.removeExtra(EXTRA_SHOW_SNACKBAR_MESSAGE)\n            }\n        }\n        onBackPressedDispatcher.addCallback(this, onBackPressedCallback)\n\n        _instrument = TestKitchenAdapter.client.getInstrument(\"apps-search\")\n            .setDefaultActionSource(\"search\")\n            .startFunnel(\"search\")\n            .also { SemanticSearchAbTest().setExperimentIfEligible(it) }\n    }\n\n    public override fun createFragment(): SearchFragment {\n        var source = intent.getSerializableExtra(Constants.INTENT_EXTRA_INVOKE_SOURCE) as InvokeSource?\n        if (source == null) {\n            when {\n                Intent.ACTION_SEND == intent.action -> { source = InvokeSource.INTENT_SHARE }\n                Intent.ACTION_PROCESS_TEXT == intent.action -> { source = InvokeSource.INTENT_PROCESS_TEXT }\n                else -> {\n                    source = InvokeSource.INTENT_UNKNOWN\n                    L.logRemoteErrorIfProd(RuntimeException(\"Unknown intent when launching SearchActivity: \" + intent.action.orEmpty()))\n                }\n            }\n        }\n        return SearchFragment.newInstance(\n            source = source,\n            query = intent.getStringExtra(QUERY_EXTRA),\n            returnLink = intent.getBooleanExtra(EXTRA_RETURN_LINK, false),\n            title = intent.getStringExtra(EXTRA_TITLE)\n        )\n    }\n\n    companion object {\n        const val QUERY_EXTRA = \"query\"\n        const val EXTRA_TITLE = \"articleTitle\"\n        const val EXTRA_RETURN_LINK = \"returnLink\"\n        const val EXTRA_RETURN_LINK_TITLE = \"returnLinkTitle\"\n        const val RESULT_LINK_SUCCESS = 97\n        const val EXTRA_SHOW_SNACKBAR_MESSAGE = \"showSnackbarMessage\"\n\n        fun newIntent(context: Context, source: InvokeSource, query: String?, returnLink: Boolean = false, title: String? = null): Intent {\n            return Intent(context, SearchActivity::class.java)\n                    .putExtra(Constants.INTENT_EXTRA_INVOKE_SOURCE, source)\n                    .putExtra(QUERY_EXTRA, query)\n                    .putExtra(EXTRA_RETURN_LINK, returnLink)\n                    .putExtra(EXTRA_TITLE, title)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/search/SearchActivity.kt","kind":"class","line":16,"members":{"EXTRA_RETURN_LINK":[68,68],"EXTRA_RETURN_LINK_TITLE":[69,69],"EXTRA_SHOW_SNACKBAR_MESSAGE":[71,71],"EXTRA_TITLE":[67,67],"QUERY_EXTRA":[66,66],"RESULT_LINK_SUCCESS":[70,70],"createFragment":[45,63],"newIntent":[73,79],"onBackPressedCallback":[18,26],"onCreate":[28,43]},"shot":"shots/code/SearchActivity.jpg","supers":["SingleFragmentActivity<SearchFragment>()"]},"SearchFragment":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"class SearchFragment : Fragment(), SearchResultCallback, RecentSearchesFragment.Callback, LanguageScrollView.Callback {\n    private var _binding: FragmentSearchBinding? = null\n    private val binding get() = _binding!!\n    private var app = WikipediaApp.instance\n    private var langBtnClicked = false\n    private var isSearchActive = false\n    private var articleTitle: String? = null\n    private var query: String? = null\n    private var returnLink = false\n    private lateinit var recentSearchesFragment: RecentSearchesFragment\n    private lateinit var searchResultsFragment: SearchResultsFragment\n    private lateinit var invokeSource: InvokeSource\n    private lateinit var initialLanguageList: String\n    var searchLanguageCode = app.languageState.appLanguageCode\n        private set\n\n    private val searchCloseListener = View.OnClickListener {\n        requireActivity().instrument?.submitInteraction(\"click\", elementId = \"search_close\")\n        closeSearch()\n        setSearchText(\"\")\n    }\n\n    private val searchQueryListener = object : SearchView.OnQueryTextListener {\n        override fun onQueryTextSubmit(queryText: String): Boolean {\n            DeviceUtil.hideSoftKeyboard(requireActivity())\n            return true\n        }\n\n        override fun onQueryTextChange(queryText: String): Boolean {\n            binding.searchCabView.setCloseButtonVisibility(queryText)\n            startSearch(queryText.trim(), force = false)\n            return true\n        }\n    }\n\n    private val requestAddLanguageLauncher = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) {\n        if (it.resultCode == RESULT_OK) {\n            var position = 0\n            val finalLanguageList = JsonUtil.encodeToString(app.languageState.appLanguageCodes)\n            if (finalLanguageList != initialLanguageList) {\n                requireActivity().setResult(RESULT_LANG_CHANGED)\n            }\n            it.data?.let { intent ->\n                if (intent.hasExtra(WikipediaLanguagesFragment.ACTIVITY_RESULT_LANG_POSITION_DATA)) {\n                    position = intent.getIntExtra(WikipediaLanguagesFragment.ACTIVITY_RESULT_LANG_POSITION_DATA, 0)\n                } else if (app.languageState.appLanguageCodes.contains(searchLanguageCode)) {\n                    position = app.languageState.appLanguageCodes.indexOf(searchLanguageCode)\n                }\n            }\n            Prefs.selectedLanguagePositionInSearch = position\n            setUpLanguageScroll(Prefs.selectedLanguagePositionInSearch)\n        }\n    }\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        if (savedInstanceState == null) {\n            handleIntent(requireActivity().intent)\n        }\n        invokeSource = requireArguments().getSerializable(Constants.INTENT_EXTRA_INVOKE_SOURCE) as InvokeSource\n        query = requireArguments().getString(ARG_QUERY)\n        articleTitle = requireArguments().getString(SearchActivity.EXTRA_TITLE)\n        returnLink = requireArguments().getBoolean(SearchActivity.EXTRA_RETURN_LINK, false)\n    }\n\n    override fun onCreateView(inflater: LayoutInflater, container: ViewGroup?, savedInstanceState: Bundle?): View {\n        _binding = FragmentSearchBinding.inflate(inflater, container, false)\n        val childFragmentManager = childFragmentManager\n        recentSearchesFragment = childFragmentManager.findFragmentById(\n                R.id.search_panel_recent) as RecentSearchesFragment\n        recentSearchesFragment.callback = this\n        searchResultsFragment = childFragmentManager.findFragmentById(\n                R.id.fragment_search_results) as SearchResultsFragment\n        searchResultsFragment.setInvokeSource(invokeSource)\n        (activity as? AppCompatActivity)?.setSupportActionBar(binding.searchToolbar)\n        binding.searchToolbar.setNavigationOnClickListener {\n\n            requireActivity().instrument?.submitInteraction(\"click\", elementId = \"search_back\")\n\n            requireActivity().supportFinishAfterTransition()\n        }\n        initialLanguageList = JsonUtil.encodeToString(app.languageState.appLanguageCodes).orEmpty()\n        binding.searchContainer.setOnClickListener { onSearchContainerClick() }\n        binding.searchLangButton.setOnClickListener { onLangButtonClick() }\n        initSearchView()\n        if (invokeSource == InvokeSource.PLACES) {\n            Prefs.selectedLanguagePositionInSearch = app.languageState.appLanguageCodes.indexOf(Prefs.placesWikiCode)\n            PlacesEvent.logImpression(\"search_view\")\n        }\n\n        SemanticSearchAbTest().runIfEligible {\n            requireActivity().instrument?.submitInteraction(\"impression\",\n                actionSubtype = invokeSource.value\n            )\n        }\n\n        return binding.root\n    }\n\n    override fun onStart() {\n        super.onStart()\n        val languagePosition = Prefs.selectedLanguagePositionInSearch\n\n        setUpLanguageScroll(languagePosition)\n        startSearch(query, langBtnClicked)\n        binding.searchCabView.setCloseButtonVisibility(query)\n        recentSearchesFragment.binding.namespacesContainer.isVisible = invokeSource != InvokeSource.PLACES\n        if (!query.isNullOrEmpty()) {\n            showPanel(PANEL_SEARCH_RESULTS)\n        }\n    }\n\n    override fun onPause() {\n        super.onPause()\n        Prefs.selectedLanguagePositionInSearch = binding.searchLanguageScrollView.selectedPosition\n    }\n\n    private fun handleIntent(intent: Intent) {\n        if (Intent.ACTION_SEND == intent.action && Constants.PLAIN_TEXT_MIME_TYPE == intent.type) {\n            requireArguments().putString(ARG_QUERY, intent.getStringExtra(Intent.EXTRA_TEXT))\n            requireArguments().putSerializable(Constants.INTENT_EXTRA_INVOKE_SOURCE, InvokeSource.INTENT_SHARE)\n        } else if (Intent.ACTION_PROCESS_TEXT == intent.action && Constants.PLAIN_TEXT_MIME_TYPE == intent.type) {\n            requireArguments().putString(ARG_QUERY, intent.getStringExtra(Intent.EXTRA_PROCESS_TEXT))\n            requireArguments().putSerializable(Constants.INTENT_EXTRA_INVOKE_SOURCE, InvokeSource.INTENT_PROCESS_TEXT)\n        }\n    }\n\n    fun setUpLanguageScroll(position: Int) {\n        var pos = position\n        searchLanguageCode = app.languageState.appLanguageCode\n        if (app.languageState.appLanguageCodes.size > 1) {\n            pos = if (app.languageState.appLanguageCodes.size > pos) pos else 0\n            binding.searchLanguageScrollViewContainer.visibility = View.VISIBLE\n            binding.searchLanguageScrollView.setUpLanguageScrollTabData(app.languageState.appLanguageCodes, pos, this)\n            binding.searchLangButton.visibility = View.GONE\n        } else {\n            binding.searchLanguageScrollViewContainer.visibility = View.GONE\n            binding.searchLangButton.visibility = View.VISIBLE\n            initLangButton()\n            recentSearchesFragment.reloadRecentSearches()\n        }\n    }\n\n    override fun onDestroyView() {\n        binding.searchCabView.setOnCloseListener(null)\n        binding.searchCabView.setOnQueryTextListener(null)\n        _binding = null\n        super.onDestroyView()\n    }\n\n    override fun switchToSearch(text: String) {\n        startSearch(term = text, force = true, isFromRecentSearch = true)\n        binding.searchCabView.setOnQueryTextListener(null)\n        binding.searchCabView.setQuery(text, false)\n        binding.searchCabView.setOnQueryTextListener(searchQueryListener)\n        binding.searchCabView.setCloseButtonVisibility(text)\n    }\n\n    override fun onAddLanguageClicked() {\n        onLangButtonClick()\n    }\n\n    override fun getLangCode(): String {\n        return searchLanguageCode\n    }\n\n    override fun setSearchText(text: String) {\n        switchToSearch(text)\n    }\n\n    override fun navigateToTitle(item: PageTitle, inNewTab: Boolean, position: Int, location: Location?, showSemanticSearchFeedback: Boolean, highlightText: String?, semanticSearchId: String?) {\n        if (!isAdded) {\n            return\n        }\n\n        if (returnLink && (if (invokeSource == InvokeSource.PLACES) location != null else true)) {\n            if (invokeSource == InvokeSource.PLACES) {\n                PlacesEvent.logAction(\"search_result_click\", \"search_view\")\n            }\n            val intent = Intent().putExtra(SearchActivity.EXTRA_RETURN_LINK_TITLE, item)\n                .putExtra(PlacesActivity.EXTRA_LOCATION, location)\n            requireActivity().setResult(SearchActivity.RESULT_LINK_SUCCESS, intent)\n            requireActivity().finish()\n        } else {\n            val historyEntry = HistoryEntry(item, HistoryEntry.SOURCE_SEARCH)\n            val intent = if (inNewTab) PageActivity.newIntentForNewTab(requireContext(), historyEntry, historyEntry.title)\n            else PageActivity.newIntentForCurrentTab(requireContext(), historyEntry, historyEntry.title, false)\n            startActivity(\n                intent\n                    .putExtra(PageActivity.EXTRA_SHOW_SEMANTIC_SEARCH_FEEDBACK, showSemanticSearchFeedback)\n                    .putExtra(PageActivity.EXTRA_SEMANTIC_SEARCH_ID, semanticSearchId)\n                    .putExtra(PageActivity.EXTRA_SEMANTIC_SEARCH_FUNNEL, requireActivity().instrument?.funnel)\n                    .putExtra(PageActivity.EXTRA_HIGHLIGHT_TEXT, highlightText)\n            )\n        }\n        closeSearch()\n        DeviceUtil.hideSoftKeyboard(requireView())\n    }\n\n    override fun onSearchSavePage(entry: HistoryEntry) {\n        SaveArticleSheetDialog.show(childFragmentManager, entry.title)\n    }\n\n    override fun onSearchProgressBar(enabled: Boolean) {\n        binding.searchProgressBar.visibility = if (enabled) View.VISIBLE else View.GONE\n    }\n\n    override fun showSemanticSearchResultsDialog(query: String) {\n        DeviceUtil.hideSoftKeyboard(requireActivity())\n        ExclusiveBottomSheetPresenter.show(childFragmentManager, SemanticSearchResultsDialog.newInstance(query, searchLanguageCode, invokeSource,\n            showFeedback = !searchResultsFragment.isSemanticSearchFeedbackShown))\n    }\n\n    override fun showSemanticSearchInfoDialog() {\n        DeviceUtil.hideSoftKeyboard(requireActivity())\n        ExclusiveBottomSheetPresenter.show(childFragmentManager, SemanticSearchInfoDialog.newInstance(searchLanguageCode))\n    }\n\n    override fun onSemanticSearchFeedbackShown() {\n        searchResultsFragment.onSemanticSearchFeedbackShown()\n    }\n\n    override fun onSemanticSearchIdLoaded(searchId: String) {\n        searchResultsFragment.setSemanticSearchId(searchId)\n    }\n\n    private fun onSearchContainerClick() {\n        // Give the root container view an empty click handler, so that click events won't\n        // get passed down to any underlying views (e.g. a PageFragment on top of which\n        // this fragment is shown)\n    }\n\n    private fun onLangButtonClick() {\n        langBtnClicked = true\n        requestAddLanguageLauncher.launch(WikipediaLanguagesActivity.newIntent(requireActivity(), InvokeSource.SEARCH))\n    }\n\n    private fun startSearch(term: String?, force: Boolean, isFromRecentSearch: Boolean = false) {\n        if (!isSearchActive) {\n            openSearch()\n        }\n        if (term.isNullOrEmpty()) {\n            showPanel(PANEL_RECENT_SEARCHES)\n        } else if (activePanel == PANEL_RECENT_SEARCHES) {\n            // start with title search...\n            showPanel(PANEL_SEARCH_RESULTS)\n        }\n        query = term\n        if (term.isNullOrBlank() && !force) {\n            return\n        }\n        binding.searchContainer.postDelayed({\n            if (!isAdded) {\n                return@postDelayed\n            }\n            when (activePanel) {\n                PANEL_SEARCH_RESULTS -> {\n                    searchResultsFragment.startSearch(term, force, isFromRecentSearch)\n                }\n            }\n        }, if (invokeSource == InvokeSource.PLACES || invokeSource == InvokeSource.VOICE || invokeSource == InvokeSource.INTENT_SHARE || invokeSource == InvokeSource.INTENT_PROCESS_TEXT) INTENT_DELAY_MILLIS else 0)\n    }\n\n    private fun openSearch() {\n        isSearchActive = true\n        binding.searchCabView.isIconified = false\n        // if we already have a previous search query, then put it into the SearchView, and it will\n        // automatically trigger the showing of the corresponding search results.\n        if (!query.isNullOrBlank()) {\n            binding.searchCabView.setQuery(query, false)\n        }\n    }\n\n    private fun closeSearch() {\n        isSearchActive = false\n        addRecentSearch(query)\n    }\n\n    private fun showPanel(panel: Int) {\n        when (panel) {\n            PANEL_RECENT_SEARCHES -> {\n                searchResultsFragment.hide()\n                recentSearchesFragment.show()\n            }\n            PANEL_SEARCH_RESULTS -> {\n                recentSearchesFragment.hide()\n                searchResultsFragment.show()\n            }\n        }\n    }\n\n    // otherwise, the recent searches must be showing:\n    private val activePanel: Int\n        get() = if (searchResultsFragment.isShowing) {\n            PANEL_SEARCH_RESULTS\n        } else {\n            // otherwise, the recent searches must be showing:\n            PANEL_RECENT_SEARCHES\n        }\n\n    private fun initSearchView() {\n        binding.searchCabView.setOnQueryTextListener(searchQueryListener)\n        binding.searchCabView.setCloseButtonClickListener(searchCloseListener)\n        binding.searchCabView.setSearchHintTextColor(ResourceUtil.getThemedColor(requireContext(),\n                R.attr.secondary_color))\n\n        binding.searchCabView.queryHint =\n            if (invokeSource == InvokeSource.PLACES) {\n                getString(R.string.places_search_hint)\n            } else {\n                getString(R.string.search_hint)\n            }\n\n        // remove focus line from search plate\n        val searchEditPlate = binding.searchCabView\n                .findViewById<View>(androidx.appcompat.R.id.search_plate)\n        searchEditPlate.setBackgroundColor(Color.TRANSPARENT)\n    }\n\n    private fun initLangButton() {\n        binding.searchLangButton.setLangCode(app.languageState.appLanguageCode.uppercase(Locale.ENGLISH))\n        FeedbackUtil.setButtonTooltip(binding.searchLangButton)\n    }\n\n    private fun addRecentSearch(title: String?) {\n        if (!title.isNullOrBlank()) {\n            lifecycleScope.launch(CoroutineExceptionHandler { _, throwable -> throwable.printStackTrace() }) {\n                AppDatabase.instance.recentSearchDao().insertRecentSearch(RecentSearch(text = title))\n                recentSearchesFragment.updateList()\n            }\n        }\n    }\n\n    override fun onLanguageTabSelected(selectedLanguageCode: String) {\n        if (langBtnClicked) {\n            // We need to skip an event when we return back from 'add languages' screen,\n            // because it triggers two events while re-drawing the UI\n            langBtnClicked = false\n        }\n        searchLanguageCode = selectedLanguageCode\n\n        recentSearchesFragment.reloadRecentSearches()\n        startSearch(query, false)\n    }\n\n    override fun onLanguageButtonClicked() {\n        onLangButtonClick()\n    }\n\n    companion object {\n        private const val ARG_QUERY = \"lastQuery\"\n        private const val PANEL_RECENT_SEARCHES = 0\n        private const val PANEL_SEARCH_RESULTS = 1\n        private const val INTENT_DELAY_MILLIS = 500L\n        const val RESULT_LANG_CHANGED = 98\n\n        fun newInstance(source: InvokeSource, query: String?, returnLink: Boolean = false, title: String? = null): SearchFragment =\n                SearchFragment().apply {\n                    arguments = Bundle().apply {\n                        putSerializable(Constants.INTENT_EXTRA_INVOKE_SOURCE, source)\n                        putString(ARG_QUERY, query)\n                        putBoolean(SearchActivity.EXTRA_RETURN_LINK, returnLink)\n                        putString(SearchActivity.EXTRA_TITLE, title)\n                    }\n                }\n    }\n}","file":"app/src/main/java/org/wikipedia/search/SearchFragment.kt","kind":"class","line":47,"members":{"ARG_QUERY":[397,397],"INTENT_DELAY_MILLIS":[400,400],"PANEL_RECENT_SEARCHES":[398,398],"PANEL_SEARCH_RESULTS":[399,399],"RESULT_LANG_CHANGED":[401,401],"_binding":[48,48],"activePanel":[338,339],"addRecentSearch":[371,378],"app":[50,50],"articleTitle":[53,53],"binding":[49,49],"closeSearch":[320,323],"getLangCode":[209,211],"handleIntent":[164,172],"initLangButton":[366,369],"initSearchView":[347,364],"initialLanguageList":[59,59],"invokeSource":[58,58],"isSearchActive":[52,52],"langBtnClicked":[51,51],"navigateToTitle":[217,244],"newInstance":[403,411],"onAddLanguageClicked":[205,207],"onCreate":[101,110],"onCreateView":[112,144],"onDestroyView":[190,195],"onLangButtonClick":[279,282],"onLanguageButtonClicked":[392,394],"onLanguageTabSelected":[380,390],"onPause":[159,162],"onSearchContainerClick":[273,277],"onSearchProgressBar":[250,252],"onSearchSavePage":[246,248],"onSemanticSearchFeedbackShown":[265,267],"onSemanticSearchIdLoaded":[269,271],"onStart":[146,157],"openSearch":[310,318],"query":[54,54],"recentSearchesFragment":[56,56],"requestAddLanguageLauncher":[82,99],"returnLink":[55,55],"searchCloseListener":[63,67],"searchLanguageCode":[60,60],"searchQueryListener":[69,80],"searchResultsFragment":[57,57],"setSearchText":[213,215],"setUpLanguageScroll":[174,188],"showPanel":[325,336],"showSemanticSearchInfoDialog":[260,263],"showSemanticSearchResultsDialog":[254,258],"startSearch":[284,308],"switchToSearch":[197,203]},"shot":"shots/code/SearchFragment.jpg","supers":["Fragment()","SearchResultCallback","RecentSearchesFragment.Callback","LanguageScrollView.Callback"]},"SearchResult":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"]],"code":"@Serializable\ndata class SearchResult(val pageTitle: PageTitle,\n                        val redirectFrom: String?,\n                        val type: SearchResultType,\n                        val coordinates: List<MwQueryPage.Coordinates>? = null,\n                        val snippet: String? = null,\n                        val indexInApiCall: Int = 0,\n                        val sectionTitle: String? = null,\n                        val editCounts: Int? = null,\n                        val referenceCounts: Int? = null,\n                        val lastUpdated: String? = null) {\n\n    @Serializable\n    enum class SearchResultType {\n        PREFIX, FULL_TEXT, HISTORY, READING_LIST, TAB_LIST, SEMANTIC\n    }\n\n    constructor(\n        page: MwQueryPage,\n        wiki: WikiSite,\n        coordinates: List<MwQueryPage.Coordinates>? = null,\n        type: SearchResultType = SearchResultType.PREFIX,\n        indexInApiCall: Int = 0,\n        sectionTitle: String? = null,\n        editCounts: Int? = null,\n        referenceCounts: Int? = null,\n        lastUpdated: String? = null\n    ) : this(\n        pageTitle = PageTitle(\n            text = page.title,\n            wiki = wiki,\n            thumbUrl = page.thumbUrl(),\n            description = page.description,\n            displayText = page.displayTitle(wiki.languageCode),\n        ).also { if (!page.sectionTitle.isNullOrEmpty()) it.fragment = StringUtil.addUnderscores(page.sectionTitle) },\n        redirectFrom = page.redirectFrom,\n        type = type,\n        coordinates = coordinates,\n        snippet = page.snippet,\n        indexInApiCall = indexInApiCall,\n        sectionTitle = page.sectionTitle,\n        editCounts = editCounts,\n        referenceCounts = referenceCounts,\n        lastUpdated = lastUpdated\n    )\n\n    constructor(pageTitle: PageTitle, searchResultType: SearchResultType = SearchResultType.PREFIX, snippet: String? = null, indexInApiCall: Int = 0) :\n            this(pageTitle, null, searchResultType, null, snippet, indexInApiCall)\n\n    val location: Location? get() {\n        return if (coordinates.isNullOrEmpty()) null else\n            Location(\"\").also {\n                it.latitude = coordinates[0].lat\n                it.longitude = coordinates[0].lon\n            }\n    }\n}","file":"app/src/main/java/org/wikipedia/search/SearchResult.kt","kind":"data class","line":10,"members":{"SearchResultType":[22,25],"constructor":[27,54],"coordinates":[14,14],"editCounts":[18,18],"indexInApiCall":[16,16],"lastUpdated":[20,20],"location":[59,65],"pageTitle":[11,11],"redirectFrom":[12,12],"referenceCounts":[19,19],"sectionTitle":[17,17],"snippet":[15,15],"type":[13,13]},"supers":[]},"SearchResultCallback":{"code":"interface SearchResultCallback {\n    fun onSearchSavePage(entry: HistoryEntry)\n    fun onSearchProgressBar(enabled: Boolean)\n    fun navigateToTitle(\n        item: PageTitle,\n        inNewTab: Boolean,\n        position: Int,\n        location: Location? = null,\n        showSemanticSearchFeedback: Boolean = false,\n        highlightText: String? = null,\n        semanticSearchId: String? = null\n    )\n\n    fun setSearchText(text: String)\n    fun showSemanticSearchResultsDialog(query: String)\n    fun showSemanticSearchInfoDialog()\n    fun onSemanticSearchFeedbackShown()\n    fun onSemanticSearchIdLoaded(searchId: String)\n}","file":"app/src/main/java/org/wikipedia/search/SearchResultCallback.kt","kind":"interface","line":7,"members":{"navigateToTitle":[10,18],"onSearchProgressBar":[9,9],"onSearchSavePage":[8,8],"onSemanticSearchFeedbackShown":[23,23],"onSemanticSearchIdLoaded":[24,24],"setSearchText":[20,20],"showSemanticSearchInfoDialog":[22,22],"showSemanticSearchResultsDialog":[21,21]},"supers":[]},"SearchResultPageItem":{"appearsIn":[["search","h-widgets","Screen \u00b7 composition"]],"code":"@Composable\nfun SearchResultPageItem(\n    modifier: Modifier = Modifier,\n    searchResultPage: SearchResult,\n    searchTerm: String?,\n    onItemClick: () -> Unit,\n    onItemLongClick: (View) -> Unit,\n) {\n    val (pageTitle, redirectFrom, type) = searchResultPage\n    var anchorView by remember { mutableStateOf<View?>(null) }\n\n    val isRedirect = !redirectFrom.isNullOrEmpty()\n\n    val iconResId = when (type) {\n        SearchResult.SearchResultType.HISTORY -> R.drawable.ic_history_24\n        SearchResult.SearchResultType.TAB_LIST -> R.drawable.ic_tab_one_24px\n        else -> R.drawable.ic_bookmark_border_white_24dp\n    }\n\n    val showImage =\n        !pageTitle.thumbUrl.isNullOrEmpty()\n\n    val boldenTitle = remember(pageTitle.displayText, searchTerm) {\n        pageTitle.displayText.toAnnotatedStringWithBoldQuery(searchTerm)\n    }\n\n    Box {\n        Row(\n            modifier = modifier\n                .fillMaxWidth()\n                .combinedClickable(\n                    onLongClick = {\n                        anchorView?.let {\n                            DeviceUtil.hideSoftKeyboard(it)\n                            onItemLongClick(it)\n                        }\n                    },\n                    onClick = {\n                        onItemClick()\n                    }\n                )\n                .padding(16.dp),\n            verticalAlignment = Alignment.CenterVertically,\n            horizontalArrangement = Arrangement.spacedBy(16.dp)\n        ) {\n            Column(\n                modifier = Modifier\n                    .weight(1f)\n            ) {\n                // Title with bold style\n                Text(\n                    text = boldenTitle,\n                    color = WikipediaTheme.colors.primaryColor,\n                    style = MaterialTheme.typography.bodyLarge\n                )\n\n                if (isRedirect) {\n                    Row(\n                        modifier = Modifier.padding(top = 2.dp)\n                    ) {\n                        Image(\n                            modifier = Modifier\n                                .size(16.dp),\n                            painter = painterResource(R.drawable.ic_subdirectory_arrow_right_black_24dp),\n                            colorFilter = ColorFilter.tint(color = WikipediaTheme.colors.placeholderColor),\n                            contentDescription = null\n                        )\n                        Text(\n                            text = stringResource(R.string.search_redirect_from, redirectFrom),\n                            color = WikipediaTheme.colors.secondaryColor,\n                            style = MaterialTheme.typography.bodyLarge.copy(\n                                fontSize = 14.sp\n                            ),\n                            maxLines = 2,\n                            overflow = TextOverflow.Ellipsis\n                        )\n                    }\n                } else {\n                    val description = pageTitle.description\n                    if (!description.isNullOrEmpty()) {\n                        Text(\n                            modifier = Modifier\n                                .padding(top = 2.dp),\n                            text = description,\n                            color = WikipediaTheme.colors.secondaryColor,\n                            style = MaterialTheme.typography.bodyLarge.copy(\n                                fontSize = 14.sp\n                            ),\n                            maxLines = 2,\n                            overflow = TextOverflow.Ellipsis\n                        )\n                    }\n                }\n            }\n\n            Row(\n                verticalAlignment = Alignment.CenterVertically,\n                horizontalArrangement = Arrangement.spacedBy(16.dp)\n            ) {\n                if (type != SearchResult.SearchResultType.PREFIX && type != SearchResult.SearchResultType.FULL_TEXT) {\n                    Image(\n                        modifier = Modifier\n                            .size(20.dp),\n                        painter = painterResource(iconResId),\n                        colorFilter = ColorFilter.tint(color = WikipediaTheme.colors.placeholderColor),\n                        contentDescription = null\n                    )\n                }\n\n                if (showImage) {\n                    val request =\n                        ImageService.getRequest(\n                            LocalContext.current,\n                            url = pageTitle.thumbUrl\n                        )\n                    AsyncImage(\n                        model = request,\n                        placeholder = BrushPainter(SolidColor(WikipediaTheme.colors.borderColor)),\n                        error = BrushPainter(SolidColor(WikipediaTheme.colors.borderColor)),\n                        contentScale = ContentScale.Crop,\n                        contentDescription = null,\n                        modifier = Modifier\n                            .size(56.dp)\n                            .clip(RoundedCornerShape(8.dp))\n                    )\n                }\n            }\n        }\n\n        // invisible anchor view for LongPressMenu\n        // using view based PopupMenu (vs pure Compose): Compose DropdownMenu does not have reliable\n        // positioning with LazyColumn items and does not anchor properly with the parent layout.\n        AndroidView(\n            factory = { ctx ->\n                View(ctx).apply {\n                    anchorView = this\n                }\n            },\n            modifier = Modifier\n                .fillMaxWidth()\n                .size(0.dp)\n        )\n    }\n}","file":"app/src/main/java/org/wikipedia/search/SearchResultsScreen.kt","kind":"composable function","line":227,"members":{},"supers":[]},"SearchResultsFragment":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-widgets","Screen \u00b7 composition"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"class SearchResultsFragment : Fragment() {\n\n    private var composeView: ComposeView? = null\n    private val viewModel: SearchResultsViewModel by viewModels()\n    private val semanticSearchAbTest = SemanticSearchAbTest()\n    val isShowing get() = composeView?.visibility == View.VISIBLE\n\n    override fun onCreateView(\n        inflater: LayoutInflater,\n        container: ViewGroup?,\n        savedInstanceState: Bundle?\n    ): View {\n\n        viewLifecycleOwner.lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                viewModel.searchTermForLogging.collectLatest { query ->\n                    if (!query.isNullOrEmpty()) {\n                        semanticSearchAbTest.runIfEligible {\n                            val isFromRecentSearch = viewModel.isFromRecentSearch\n                            requireActivity().instrument?.submitInteraction(\"init\",\n                                actionSubtype = if (isFromRecentSearch) \"recent_search\" else null,\n                                elementId = if (isFromRecentSearch) \"search_result\" else null,\n                                actionContext = mapOf(\n                                    \"query\" to query,\n                                    \"query_trunc\" to (query.length > 256)\n                                )\n                            )\n                        }\n                    }\n                }\n            }\n        }\n        viewLifecycleOwner.lifecycleScope.launch {\n            repeatOnLifecycle(Lifecycle.State.CREATED) {\n                viewModel.lexicalResultsForLogging.collectLatest { data ->\n                    if (data != null) {\n                        requireActivity().instrument?.submitInteraction(\n                            \"show_search_result\",\n                            actionContext = viewModel.getStandardEventActionContext()\n                        )\n                        submitSemanticLexicalResultEvent(\"impression\")\n                    }\n                }\n            }\n        }\n\n        return ComposeView(requireActivity()).apply {\n            composeView = this\n            setContent {\n                BaseTheme {\n                    SearchResultsScreen(\n                        viewModel = viewModel,\n                        modifier = Modifier.fillMaxSize(),\n                        onNavigateToTitle = { result, inNewTab, position, location ->\n\n                            requireActivity().instrument?.submitInteraction(\"search_result_click\",\n                                pageData = TestKitchenAdapter.getPageData(result.pageTitle),\n                                actionContext = viewModel.getStandardEventActionContext(result)\n                            )\n\n                            submitSemanticLexicalResultEvent(\"click\", result)\n\n                            callback()?.navigateToTitle(result.pageTitle, inNewTab, position, location)\n                        },\n                        onItemLongClick = { view, searchResult, position ->\n                            val entry =\n                                HistoryEntry(searchResult.pageTitle, HistoryEntry.SOURCE_SEARCH)\n                            LongPressMenu(\n                                view,\n                                callback = SearchResultLongPressHandler(callback(), position)\n                            ).show(entry)\n                        },\n                        onCloseSearch = { requireActivity().finish() },\n                        onRetrySearch = {\n                            viewModel.refreshSearchResults()\n                        },\n                        onLanguageClick = { position ->\n                            if (isAdded && position >= 0) {\n                                (requireParentFragment() as SearchFragment).setUpLanguageScroll(\n                                    position\n                                )\n                            }\n                        },\n                        onLoading = { enabled ->\n                            callback()?.onSearchProgressBar(enabled)\n                        },\n                        onSemanticSearchClick = { searchTerm, isFirstUse ->\n                            semanticSearchAbTest.runIfEligible {\n                                requireActivity().instrument?.submitInteraction(\"click\",\n                                    elementId = \"enter_semantic_search\"\n                                )\n                                if (isFirstUse) {\n                                    requireActivity().instrument?.submitInteraction(\"click\",\n                                        elementId = \"try_now_button\"\n                                    )\n                                }\n                            }\n                            searchTerm?.let {\n                                callback()?.showSemanticSearchResultsDialog(it)\n                            }\n                        },\n                        onSemanticSearchInfoClick = {\n                            semanticSearchAbTest.runIfEligible {\n                                requireActivity().instrument?.submitInteraction(\"click\",\n                                    elementId = \"info_button\"\n                                )\n                            }\n                            callback()?.showSemanticSearchInfoDialog()\n                        },\n                        onSemanticSearchCloseClick = {\n                            semanticSearchAbTest.runIfEligible {\n                                requireActivity().instrument?.submitInteraction(\"click\",\n                                    elementId = \"close_semantic_button\"\n                                )\n                            }\n                            val messageText = requireContext().getString(searchLanguageCode, R.string.semantic_search_snackbar_message)\n                            val actionButtonText = requireContext().getString(searchLanguageCode, R.string.semantic_search_snackbar_action_label)\n                            FeedbackUtil.makeSnackbar(requireActivity(), messageText)\n                                .setAction(actionButtonText) {\n                                    startActivity(SettingsActivity.newIntent(requireContext()))\n                                }\n                                .apply { view.setLayoutDirectionByLang(searchLanguageCode) }\n                                .show()\n                        }\n                    )\n                }\n            }\n        }\n    }\n\n    fun show() {\n        composeView?.visibility = View.VISIBLE\n    }\n\n    fun hide() {\n        composeView?.visibility = View.GONE\n    }\n\n    fun startSearch(term: String?, force: Boolean, isFromRecentSearch: Boolean) {\n        if (!force && viewModel.searchTerm.value == term && viewModel.languageCode.value == searchLanguageCode) {\n            return\n        }\n\n        requireActivity().instrument?.setDefaultMediaWikiData(WikiSite.forLanguageCode(searchLanguageCode).dbName())\n        viewModel.updateLanguageCode(searchLanguageCode)\n        viewModel.updateSearchTerm(if (term.isNullOrBlank()) \"\" else term)\n        viewModel.isFromRecentSearch = isFromRecentSearch\n\n        // If user changes the language, make sure to turn off hybrid search screen.\n        if (force) {\n            viewModel.refreshSearchResults()\n        }\n    }\n\n    private fun callback(): SearchResultCallback? {\n        return getCallback(this, SearchResultCallback::class.java)\n    }\n\n    private fun submitSemanticLexicalResultEvent(action: String, result: SearchResult? = null) {\n        semanticSearchAbTest.runIfEligible {\n            val isTreatment = semanticSearchAbTest.group == ABTest.GROUP_2\n            requireActivity().instrument?.submitInteraction(action,\n                elementId = \"search_result\",\n                actionSubtype = \"lexical_result\",\n                actionContext = if (isTreatment) viewModel.getSemanticEventActionContext(result) else viewModel.getStandardEventActionContext(result)\n            )\n        }\n    }\n\n    fun setInvokeSource(invokeSource: Constants.InvokeSource) {\n        viewModel.invokeSource = invokeSource\n    }\n\n    fun setSemanticSearchId(searchId: String) {\n        viewModel.lastXSearchIdSemantic = searchId\n    }\n\n    val isSemanticSearchFeedbackShown get() = viewModel.isSemanticSearchFeedbackShown\n\n    fun onSemanticSearchFeedbackShown() {\n        viewModel.isSemanticSearchFeedbackShown = true\n    }\n\n    private val searchLanguageCode\n        get() =\n            if (isAdded) (requireParentFragment() as SearchFragment).searchLanguageCode else WikipediaApp.instance.languageState.appLanguageCode\n\n    override fun onDestroyView() {\n        super.onDestroyView()\n        composeView = null\n    }\n}","file":"app/src/main/java/org/wikipedia/search/SearchResultsFragment.kt","kind":"class","line":34,"members":{"callback":[188,190],"composeView":[36,36],"hide":[168,170],"isSemanticSearchFeedbackShown":[211,211],"isShowing":[39,39],"onCreateView":[41,162],"onDestroyView":[221,224],"onSemanticSearchFeedbackShown":[213,215],"searchLanguageCode":[217,217],"semanticSearchAbTest":[38,38],"setInvokeSource":[203,205],"setSemanticSearchId":[207,209],"show":[164,166],"startSearch":[172,186],"submitSemanticLexicalResultEvent":[192,201],"viewModel":[37,37]},"shot":"shots/code/SearchResultsFragment.jpg","supers":["Fragment()"]},"SearchResultsScreen":{"appearsIn":[["search","h-widgets","Screen \u00b7 composition"]],"code":"@OptIn(FlowPreview::class)\n@Composable\nfun SearchResultsScreen(\n    modifier: Modifier = Modifier,\n    viewModel: SearchResultsViewModel,\n    onNavigateToTitle: (SearchResult, Boolean, Int, Location?) -> Unit,\n    onItemLongClick: (View, SearchResult, Int) -> Unit,\n    onLanguageClick: (Int) -> Unit,\n    onSemanticSearchClick: (String?, Boolean) -> Unit,\n    onSemanticSearchInfoClick: () -> Unit,\n    onSemanticSearchCloseClick: () -> Unit,\n    onCloseSearch: () -> Unit,\n    onRetrySearch: () -> Unit,\n    onLoading: (Boolean) -> Unit\n) {\n    val searchResults = viewModel.searchResultsFlow.collectAsLazyPagingItems()\n    val searchTerm = viewModel.searchTerm.collectAsState()\n    val isSemanticSearchEnabledState = viewModel.isSemanticSearchEnabled.collectAsState()\n    val isSemanticSearchEnabled = isSemanticSearchEnabledState.value && viewModel.invokeSource != Constants.InvokeSource.PLACES\n    val isSemanticSearchFirstUse = viewModel.isSemanticSearchFirstUse.collectAsState()\n    val loadState = searchResults.loadState\n    val countsPerLanguageCode = viewModel.countsPerLanguageCode\n\n    val languageCode = viewModel.languageCode.collectAsState()\n    val layoutDirection =\n        if (L10nUtil.isLangRTL(languageCode.value)) LayoutDirection.Rtl else LayoutDirection.Ltr\n\n    // this is a callback to show loading indicator in the SearchFragment.\n    // It is placed outside the UI logic to prevent flickering. We need to show the loader both initial load (refresh) and pagination (append) without hiding the list or conflicting with other UI states.\n    val isLoading = loadState.refresh is LoadState.Loading || loadState.append is LoadState.Loading\n    LaunchedEffect(isLoading) {\n        onLoading(isLoading)\n    }\n\n    // used to prevent flickering in the error state.\n    var isErrorState by remember { mutableStateOf(false) }\n    LaunchedEffect(searchResults) {\n        snapshotFlow { searchResults.loadState.refresh is LoadState.Error }\n            .debounce(200L.milliseconds)\n            .collect { isErrorState = it }\n    }\n\n    val shouldShowNoResults =\n        loadState.append is LoadState.NotLoading &&\n        loadState.append.endOfPaginationReached &&\n        searchResults.itemCount == 0 &&\n        !isSemanticSearchEnabled\n\n    val shouldLogNoResultsImpression =\n        shouldShowNoResults &&\n        countsPerLanguageCode.isNotEmpty() &&\n        viewModel.invokeSource == Constants.InvokeSource.PLACES\n\n    val shouldShowSemanticSearchEntryPoint =\n        isSemanticSearchEnabled &&\n                !searchTerm.value.isNullOrBlank() &&\n                loadState.refresh !is LoadState.Error &&\n                !isErrorState\n\n    LaunchedEffect(shouldLogNoResultsImpression) {\n        if (shouldLogNoResultsImpression) {\n            PlacesEvent.logAction(\"no_results_impression\", \"search_view\")\n        }\n    }\n\n    CompositionLocalProvider(LocalLayoutDirection provides layoutDirection) {\n        LazyColumn(\n            modifier = modifier\n        ) {\n            if (shouldShowSemanticSearchEntryPoint) {\n                item {\n                    SemanticSearchEntryCard(\n                        languageCode = languageCode.value,\n                        searchTerm = searchTerm.value,\n                        onCloseClick = {\n                            viewModel.disableSemanticSearch()\n                            onSemanticSearchCloseClick()\n                        },\n                        onInfoBtnClick = { onSemanticSearchInfoClick() },\n                        onSemanticSearchClick = {\n                            val isSemanticSearchFirstUse = isSemanticSearchFirstUse.value\n                            if (isSemanticSearchFirstUse) {\n                                Prefs.isSemanticSearchFirstUse = false\n                            }\n                            onSemanticSearchClick(searchTerm.value, isSemanticSearchFirstUse)\n                        },\n                        isFirstUse = isSemanticSearchFirstUse.value\n                    )\n                }\n            }\n\n            when {\n                loadState.refresh is LoadState.Loading -> {} // when offline prevents UI from loading old list\n\n                loadState.refresh is LoadState.Error -> {\n                    val error = (loadState.refresh as LoadState.Error).error\n                    item {\n                        Box(\n                            modifier = Modifier.fillParentMaxSize(),\n                            contentAlignment = Alignment.Center\n                        ) {\n                            WikiErrorView(\n                                caught = error,\n                                errorClickEvents = WikiErrorClickEvents(\n                                    backClickListener = { onCloseSearch() },\n                                    retryClickListener = { onRetrySearch() }\n                                )\n                            )\n                        }\n                    }\n                }\n\n                loadState.append is LoadState.NotLoading && loadState.append.endOfPaginationReached && searchResults.itemCount == 0 -> {\n                    if (!isSemanticSearchEnabled) {\n                        noSearchResults(\n                            countsPerLanguageCode = countsPerLanguageCode,\n                            onLanguageClick = onLanguageClick\n                        )\n                    }\n                }\n\n                else -> {\n                    searchResultItems(\n                        searchResultsPage = searchResults,\n                        searchTerm = searchTerm.value,\n                        onItemClick = onNavigateToTitle,\n                        onItemLongClick = onItemLongClick\n                    )\n                }\n            }\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/search/SearchResultsScreen.kt","kind":"composable function","line":67,"members":{},"shot":"shots/code/SearchResultsScreen.jpg","supers":[]},"SearchResultsViewModel":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"class SearchResultsViewModel : ViewModel() {\n    private val semanticSearchAbTest = SemanticSearchAbTest()\n    private val semanticSearchEnabledPrefUpdates = Prefs.observeKeys(\n        R.string.preference_key_semantic_search_enabled,\n        R.string.preference_key_semantic_search_is_test_active, // TODO: remove this before release\n        R.string.preference_key_semantic_search_override_supported_language // TODO: remove this before release\n    )\n    private val semanticSearchIsFirstUsePrefUpdates = Prefs.observeKeys(\n        R.string.preference_key_semantic_search_first_use\n    )\n    private val batchSize = 10\n    private val delayMillis = 200L\n    var countsPerLanguageCode = mutableListOf<Pair<String, Int>>()\n    var isSemanticSearchFeedbackShown = false\n    var isFromRecentSearch = false\n\n    lateinit var invokeSource: Constants.InvokeSource\n\n    private val _searchTerm = MutableStateFlow<String?>(null)\n    var searchTerm = _searchTerm.asStateFlow()\n\n    private val _searchTermForLogging = MutableSharedFlow<String?>()\n    var searchTermForLogging = _searchTermForLogging.asSharedFlow()\n    private val _lexicalResultsForLogging = MutableStateFlow<List<SearchResult>?>(null)\n    var lexicalResultsForLogging = _lexicalResultsForLogging.asStateFlow()\n\n    private var _languageCode = MutableStateFlow(WikipediaApp.instance.languageState.appLanguageCode)\n    var languageCode = _languageCode.asStateFlow()\n\n    private var _refreshSearchResults = MutableStateFlow(0)\n\n    private var lastXSearchIdPrefix = \"\"\n    private var lastXSearchIdFullText = \"\"\n    var lastXSearchIdSemantic = \"\"\n    private var isSemanticSearchExposureSent = false\n\n    val isSemanticSearchEnabled = combine(\n        _languageCode,\n        semanticSearchEnabledPrefUpdates\n    ) { currentLanguageCode, _ ->\n        semanticSearchAbTest.isSemanticSearchEnabled(currentLanguageCode)\n    }.distinctUntilChanged().stateIn(\n        viewModelScope,\n        SharingStarted.Eagerly,\n        semanticSearchAbTest.isSemanticSearchEnabled(_languageCode.value)\n    )\n\n    val isSemanticSearchFirstUse = semanticSearchIsFirstUsePrefUpdates\n        .map { Prefs.isSemanticSearchFirstUse }\n        .distinctUntilChanged()\n        .stateIn(\n            viewModelScope,\n            SharingStarted.Eagerly,\n            Prefs.isSemanticSearchFirstUse\n        )\n\n    @OptIn(\n        FlowPreview::class,\n        ExperimentalCoroutinesApi::class\n    ) // TODO: revisit if the debounce method changed.\n    val searchResultsFlow =\n        combine(_searchTerm.debounce(delayMillis.milliseconds), _languageCode, _refreshSearchResults) { term, lang, _ ->\n            Pair(term, lang)\n        }.flatMapLatest { (term, lang) ->\n            // A language change or refresh can re-emit the previous debounced term before the new one settles.\n            if (term == _searchTerm.value) {\n                _searchTermForLogging.emit(term)\n                if (!term.isNullOrBlank()) {\n                    maybeSendSemanticSearchExposure(lang)\n                }\n            }\n            val repository = StandardSearchRepository()\n            Pager(PagingConfig(pageSize = batchSize)) {\n                SearchResultsPagingSource(\n                    searchTerm = term,\n                    languageCode = lang,\n                    countsPerLanguageCode = countsPerLanguageCode,\n                    invokeSource = invokeSource,\n                    repository = repository,\n                    onFirstPageLoaded = { result ->\n                        lastXSearchIdPrefix = result.xSearchIdPrefix.orEmpty()\n                        lastXSearchIdFullText = result.xSearchIdFullText.orEmpty()\n                        _lexicalResultsForLogging.value = result.results\n                    }\n                )\n            }.flow\n        }.cachedIn(viewModelScope)\n\n    fun updateSearchTerm(term: String?) {\n        if (_searchTerm.value != term) {\n            lastXSearchIdSemantic = \"\"\n        }\n        _searchTerm.value = term\n    }\n\n    fun updateLanguageCode(code: String) {\n        if (_languageCode.value != code) {\n            lastXSearchIdSemantic = \"\"\n        }\n        _languageCode.value = code\n    }\n\n    fun refreshSearchResults() {\n        _refreshSearchResults.value += 1\n    }\n\n    fun getStandardEventActionContext(result: SearchResult? = null): Map<String, Any> {\n        return buildMap {\n            put(\"search_id_pre\", lastXSearchIdPrefix)\n            put(\"search_id_ful\", lastXSearchIdFullText)\n            if (result != null) {\n                put(\"position\", result.indexInApiCall)\n                put(\"type\", result.type)\n            }\n        }\n    }\n\n    fun getSemanticEventActionContext(result: SearchResult? = null): Map<String, Any> {\n        return buildMap {\n            put(\"search_id_pre\", lastXSearchIdPrefix)\n            put(\"search_id_ful\", lastXSearchIdFullText)\n            put(\"search_id_sem\", lastXSearchIdSemantic)\n            if (result != null) {\n                put(\"position\", result.indexInApiCall)\n                put(\"type\", result.type)\n            }\n        }\n    }\n\n    // Sent for both groups at the point where the semantic search entry card can appear.\n    private fun maybeSendSemanticSearchExposure(languageCode: String) {\n        if (isSemanticSearchExposureSent || invokeSource == Constants.InvokeSource.PLACES ||\n            !Prefs.isSemanticSearchEnabled || !semanticSearchAbTest.isSemanticSearchEligible(languageCode)) {\n            return\n        }\n        isSemanticSearchExposureSent = true\n        semanticSearchAbTest.maybeSendExposureEvent()\n    }\n\n    fun disableSemanticSearch() {\n        Prefs.isSemanticSearchEnabled = false\n    }\n\n    class SearchResultsPagingSource(\n        private val searchTerm: String?,\n        private val languageCode: String?,\n        private var countsPerLanguageCode: MutableList<Pair<String, Int>>,\n        private var invokeSource: Constants.InvokeSource,\n        private val repository: SearchRepository<StandardSearchResults>,\n        private val onFirstPageLoaded: (StandardSearchResults) -> Unit\n    ) : PagingSource<Int, SearchResult>() {\n\n        override suspend fun load(params: LoadParams<Int>): LoadResult<Int, SearchResult> {\n            return try {\n                if (searchTerm.isNullOrEmpty() || languageCode.isNullOrEmpty()) {\n                    return LoadResult.Page(emptyList(), null, null)\n                }\n\n                val result = repository.search(\n                    searchTerm = searchTerm,\n                    languageCode = languageCode,\n                    invokeSource = invokeSource,\n                    continuation = params.key,\n                    batchSize = params.loadSize,\n                    isPrefixSearch = params.key == null,\n                    countsPerLanguageCode = countsPerLanguageCode\n                )\n\n                if (params.key == null) {\n                    onFirstPageLoaded(result)\n                }\n\n                return LoadResult.Page(\n                    result.results,\n                    null,\n                    result.continuation\n                )\n            } catch (e: CancellationException) {\n                throw e\n            } catch (e: Exception) {\n                LoadResult.Error(e)\n            }\n        }\n\n        override fun getRefreshKey(state: PagingState<Int, SearchResult>): Int? {\n            return null\n        }\n    }\n\n    companion object {\n        fun buildList(\n            response: MwQueryResponse?,\n            invokeSource: Constants.InvokeSource,\n            wikiSite: WikiSite,\n            type: SearchResult.SearchResultType\n        ): List<SearchResult> {\n            return response?.query?.pages?.let { list ->\n                (if (invokeSource == Constants.InvokeSource.PLACES)\n                    list.filter { it.coordinates != null } else list).sortedBy { it.index }\n                    .map { SearchResult(it, wikiSite, it.coordinates, type, indexInApiCall = it.index) }\n            } ?: emptyList()\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/search/SearchResultsViewModel.kt","kind":"class","line":33,"members":{"SearchResultsPagingSource":[176,220],"_languageCode":[59,59],"_lexicalResultsForLogging":[56,56],"_refreshSearchResults":[62,62],"_searchTerm":[51,51],"_searchTermForLogging":[54,54],"batchSize":[43,43],"buildList":[223,234],"countsPerLanguageCode":[45,45],"delayMillis":[44,44],"disableSemanticSearch":[172,174],"getSemanticEventActionContext":[150,160],"getStandardEventActionContext":[139,148],"invokeSource":[49,49],"isFromRecentSearch":[47,47],"isSemanticSearchEnabled":[69,78],"isSemanticSearchExposureSent":[67,67],"isSemanticSearchFeedbackShown":[46,46],"isSemanticSearchFirstUse":[80,87],"languageCode":[60,60],"lastXSearchIdFullText":[65,65],"lastXSearchIdPrefix":[64,64],"lastXSearchIdSemantic":[66,66],"lexicalResultsForLogging":[57,57],"maybeSendSemanticSearchExposure":[162,170],"refreshSearchResults":[135,137],"searchResultsFlow":[89,119],"searchTerm":[52,52],"searchTermForLogging":[55,55],"semanticSearchAbTest":[34,34],"semanticSearchEnabledPrefUpdates":[35,39],"semanticSearchIsFirstUsePrefUpdates":[40,42],"updateLanguageCode":[128,133],"updateSearchTerm":[121,126]},"supers":["ViewModel()"]},"ServiceFactory":{"appearsIn":[["activity","h-classes","Logic \u00b7 class diagram"],["activity","h-sequence","Open the Activity tab, logged in \u00b7 sequence"],["home","h-classes","Logic \u00b7 class diagram"],["home","h-sequence","Load more of the Community feed \u00b7 sequence"],["index","h-services","Services \u00b7 what the screens share"],["places","h-classes","Logic \u00b7 class diagram"],["places","h-sequence","Pan the map and open a place \u00b7 sequence"],["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"object ServiceFactory {\n\n    private const val SERVICE_CACHE_SIZE = 8\n\n    private val SERVICE_CACHE = lruCache<WikiSite, Service>(SERVICE_CACHE_SIZE, create = {\n        // This method is called in the get() method if a value does not already exist.\n        createRetrofit(it, getBasePath(it)).create<Service>()\n    })\n\n    private val REST_SERVICE_CACHE = lruCache<WikiSite, RestService>(SERVICE_CACHE_SIZE, create = {\n        createRetrofit(it, getRestBasePath(it)).create<RestService>()\n    })\n\n    private val CORE_REST_SERVICE_CACHE = lruCache<WikiSite, CoreRestService>(SERVICE_CACHE_SIZE, create = {\n        createRetrofit(it, it.url() + \"/\" + CoreRestService.CORE_REST_API_PREFIX).create<CoreRestService>()\n    })\n\n    private val ANALYTICS_REST_SERVICE_CACHE = lruCache<DestinationEventService, EventService>(SERVICE_CACHE_SIZE, create = {\n        val intakeBaseUriOverride = Prefs.eventPlatformIntakeUriOverride.orEmpty().ifEmpty { it.baseUri }\n        createRetrofit(null, intakeBaseUriOverride).create<EventService>()\n    })\n\n    fun get(wiki: WikiSite): Service {\n        return SERVICE_CACHE[wiki]!!\n    }\n\n    fun getRest(wiki: WikiSite): RestService {\n        return REST_SERVICE_CACHE[wiki]!!\n    }\n\n    fun getCoreRest(wiki: WikiSite): CoreRestService {\n        return CORE_REST_SERVICE_CACHE[wiki]!!\n    }\n\n    fun getAnalyticsRest(destinationEventService: DestinationEventService): EventService {\n        return ANALYTICS_REST_SERVICE_CACHE[destinationEventService]!!\n    }\n\n    operator fun <T> get(wiki: WikiSite, baseUrl: String?, service: Class<T>): T {\n        val r = createRetrofit(wiki, baseUrl.orEmpty().ifEmpty { wiki.url() + \"/\" })\n        return r.create(service)\n    }\n\n    fun getBasePath(wiki: WikiSite): String {\n        var path = wiki.url()\n        if (!path.endsWith(\"/\")) {\n            path += \"/\"\n        }\n        return path\n    }\n\n    fun getRestBasePath(wiki: WikiSite): String {\n        var path = if (Prefs.restbaseUriFormat.isEmpty()) wiki.url() + \"/\" + RestService.REST_API_PREFIX\n        else String.format(Prefs.restbaseUriFormat, \"https\", wiki.authority())\n        if (!path.endsWith(\"/\")) {\n            path += \"/\"\n        }\n        return path\n    }\n\n    fun createRetrofit(wiki: WikiSite?, baseUrl: String, readTimeoutSec: Long = OkHttpConnectionFactory.DEFAULT_READ_TIMEOUT_SEC): Retrofit {\n        val builder = OkHttpConnectionFactory.client.newBuilder()\n        builder.readTimeout(readTimeoutSec, TimeUnit.SECONDS)\n        builder.interceptors().add(builder.interceptors().indexOfFirst { it is HttpLoggingInterceptor }, LanguageVariantHeaderInterceptor(wiki))\n\n        return Retrofit.Builder()\n            .baseUrl(baseUrl)\n            .client(builder.build())\n            .addConverterFactory(MwExceptionConverterFactory())\n            .build()\n    }\n\n    private class LanguageVariantHeaderInterceptor(private val wiki: WikiSite?) : Interceptor {\n        @Throws(IOException::class)\n        override fun intercept(chain: Interceptor.Chain): Response {\n            var request = chain.request().newBuilder()\n                .header(\"Accept-Language\", WikipediaApp.instance.getAcceptLanguage(wiki))\n                .build()\n            return chain.proceed(request)\n        }\n    }\n}","file":"app/src/main/java/org/wikipedia/dataclient/ServiceFactory.kt","kind":"object","line":18,"members":{"ANALYTICS_REST_SERVICE_CACHE":[35,38],"CORE_REST_SERVICE_CACHE":[31,33],"LanguageVariantHeaderInterceptor":[90,98],"REST_SERVICE_CACHE":[27,29],"SERVICE_CACHE":[22,25],"SERVICE_CACHE_SIZE":[20,20],"createRetrofit":[78,88],"get":[40,42],"getAnalyticsRest":[52,54],"getBasePath":[61,67],"getCoreRest":[48,50],"getRest":[44,46],"getRestBasePath":[69,76]},"supers":[]},"StandardSearchRepository":{"appearsIn":[["search","h-classes","Logic \u00b7 class diagram"],["search","h-sequence","Type a query \u00b7 sequence"]],"code":"class StandardSearchRepository : SearchRepository<StandardSearchResults> {\n    override suspend fun search(\n        searchTerm: String,\n        languageCode: String,\n        invokeSource: Constants.InvokeSource,\n        continuation: Int?,\n        batchSize: Int,\n        isPrefixSearch: Boolean,\n        countsPerLanguageCode: MutableList<Pair<String, Int>>\n    ): StandardSearchResults {\n        val wikiSite = WikiSite.forLanguageCode(languageCode)\n        val resultList = mutableListOf<SearchResult>()\n        var response: MwQueryResponse? = null\n        var currentContinuation = continuation\n        var lastXSearchIdPrefix: String? = null\n        var lastXSearchIdFullText: String? = null\n\n        if (isPrefixSearch) {\n            if (searchTerm.length >= 2 && invokeSource != Constants.InvokeSource.PLACES) {\n                withContext(Dispatchers.IO) {\n                    listOf(async {\n                        getSearchResultsFromTabs(wikiSite, searchTerm)\n                    }, async {\n                        AppDatabase.instance.historyEntryWithImageDao().findHistoryItem(wikiSite, searchTerm)\n                    }, async {\n                        AppDatabase.instance.readingListPageDao().findPageForSearchQueryInAnyList(wikiSite, searchTerm)\n                    }).awaitAll().forEach {\n                        resultList.addAll(it.results.take(1))\n                    }\n                }\n            }\n            val prefixResponse = ServiceFactory.get(wikiSite).prefixSearchResponse(searchTerm, batchSize, 0)\n            lastXSearchIdPrefix = prefixResponse.headers()[\"x-search-id\"]\n            response = prefixResponse.body()\n            currentContinuation = 0\n        }\n\n        resultList.addAll(SearchResultsViewModel.buildList(response, invokeSource, wikiSite, SearchResult.SearchResultType.PREFIX))\n\n        if (resultList.size < batchSize) {\n            val fullTextResponse = ServiceFactory.get(wikiSite)\n                .fullTextSearchResponse(searchTerm, batchSize, currentContinuation)\n            lastXSearchIdFullText = fullTextResponse.headers()[\"x-search-id\"]\n            response = fullTextResponse.body()\n            currentContinuation = response?.continuation?.gsroffset\n            resultList.addAll(SearchResultsViewModel.buildList(response, invokeSource, wikiSite, SearchResult.SearchResultType.FULL_TEXT))\n        }\n\n        if (resultList.isEmpty() && response?.continuation == null) {\n            countsPerLanguageCode.clear()\n            WikipediaApp.instance.languageState.appLanguageCodes.forEach { langCode ->\n                var countResultSize = 0\n                if (langCode != languageCode) {\n                    val prefixSearchResponse = ServiceFactory.get(WikiSite.forLanguageCode(langCode))\n                        .prefixSearch(searchTerm, batchSize, 0)\n                    prefixSearchResponse.query?.pages?.let {\n                        countResultSize = it.size\n                    }\n                    if (countResultSize == 0) {\n                        val fullTextSearchResponse = ServiceFactory.get(WikiSite.forLanguageCode(langCode))\n                            .fullTextSearch(searchTerm, batchSize, null)\n                        countResultSize = fullTextSearchResponse.query?.pages?.size ?: 0\n                    }\n                }\n                countsPerLanguageCode.add(langCode to countResultSize)\n            }\n        }\n\n        return StandardSearchResults(\n            results = resultList.distinctBy { it.pageTitle.prefixedText }.toMutableList(),\n            continuation = currentContinuation,\n            xSearchIdPrefix = lastXSearchIdPrefix,\n            xSearchIdFullText = lastXSearchIdFullText\n        )\n    }\n\n    private fun getSearchResultsFromTabs(wikiSite: WikiSite, searchTerm: String): SearchResults {\n        WikipediaApp.instance.tabList.forEach { tab ->\n            tab.backStackPositionTitle?.let {\n                if (wikiSite == it.wikiSite && StringUtil.fromHtml(it.displayText).contains(searchTerm, true)) {\n                    return SearchResults(mutableListOf(SearchResult(it, SearchResult.SearchResultType.TAB_LIST)))\n                }\n            }\n        }\n        return SearchResults()\n    }\n}","file":"app/src/main/java/org/wikipedia/search/StandardSearchRepository.kt","kind":"class","line":15,"members":{"getSearchResultsFromTabs":[91,100],"search":[16,89]},"supers":["SearchRepository<StandardSearchResults>"]}},"sourceUrl":"https://github.com/wikimedia/apps-android-wikipedia/blob/a94b2dd658c6a6bdc7f131c5bf5fa97ba9ae6bfd/"};
